function generateSimpleDescription(data) {
  const parts = [];
  parts.push(`## 问题描述
${data.problem}`);
  if (data.rootCause) {
    parts.push(`
## 根因分析
${data.rootCause}`);
  }
  if (data.solution) {
    parts.push(`
## 解决方案
${data.solution}`);
  }
  if (data.checkpoints.length > 0) {
    parts.push(`
## 检查点`);
    data.checkpoints.forEach((cp, idx) => {
      parts.push(`- CP-${idx + 1}: ${cp}`);
    });
  }
  if (data.relatedFiles.length > 0) {
    parts.push(`
## 相关文件`);
    data.relatedFiles.forEach((f) => {
      parts.push(`- ${f}`);
    });
  }
  if (data.notes) {
    parts.push(`
## 备注
${data.notes}`);
  }
  return parts.join(`
`);
}
