    subtasks: 0,
    subtaskCompletionRate: 0,
    byStatus: {
      open: 0,
      in_progress: 0,
      wait_review: 0,
      wait_qa: 0,
      wait_evaluation: 0,
      resolved: 0,
      closed: 0,
      abandoned: 0,
      failed: 0
    },
    byPriority: {
      P0: 0,
      P1: 0,
      P2: 0,
      P3: 0,
      Q1: 0,
      Q2: 0,
      Q3: 0,
      Q4: 0
    },
    blocked: 0,
    stale: 0,
    orphan: 0,
    cycle: 0,
    orphanSubtasks: 0,
    abandonedResidual: 0,
    resolvedWithoutVerification: 0,
    inconsistentStatus: 0,
    fileNotFound: 0,
    ignored: ignoredCount,
    missingCreatedBy: 0
