      taskId: rd.from,
      type: "redundant_dep",
      severity: "low",
      message: `Redundant dependency: ${rd.from} → ${rd.to} (can be reached via ${rd.viaPath.join(" → ")})`,
      suggestion: `Can remove direct dependency ${rd.from} → ${rd.to}`,
      details: { from: rd.from, to: rd.to, viaPath: rd.viaPath }
