function isMeaninglessSlug(slug) {
  if (!slug || slug.length === 0)
    return true;
  if (/^t[0-9a-z]+$/.test(slug) && slug.length <= 12)
    return true;
  if (slug === "task" || slug.startsWith("task-"))
    return true;
  return false;
}
