var DEFAULT_HOOKS = {
  "pre-commit": {
    type: "pre-commit",
    command: "npm test",
    description: "Run tests before commit"
  },
  "pre-publish": {
    type: "pre-publish",
    command: "npm run test:coverage",
    description: "Run tests with coverage before publish"
  }
};

class Pre {
  projectRoot;
  gitDir;
  packageJsonPath;
  constructor(projectRoot = process.cwd()) {
    this.projectRoot = path3.resolve(projectRoot);
    this.gitDir = path3.join(this.projectRoot, ".git");
    this.packageJsonPath = path3.join(this.projectRoot, "package.json");
  }
  installPreCommit() {
    const hookPath = this.getHookPath("pre-commit");
    const command = DEFAULT_HOOKS["pre-commit"].command;
    this.ensureHooksDir();
    fs5.writeFileSync(hookPath, `#!/bin/sh
# pre-commit hook — auto-generated by projmnt4claude
${command}
`, "utf-8");
    fs5.chmodSync(hookPath, 493);
    return hookPath;
  }
  installPrePublish() {
    const pkg = json(this.packageJsonPath);
    const scripts = pkg.read().scripts || {};
    scripts.prepublishOnly = DEFAULT_HOOKS["pre-publish"].command;
    pkg.update((data) => ({
      ...data,
      scripts
    }));
  }
  installAll() {
    this.installPreCommit();
    this.installPrePublish();
  }
  removePreCommit() {
    const hookPath = this.getHookPath("pre-commit");
    if (fs5.existsSync(hookPath)) {
      const content = fs5.readFileSync(hookPath, "utf-8");
      if (content.includes("auto-generated by projmnt4claude")) {
        fs5.unlinkSync(hookPath);
        return true;
      }
    }
    return false;
  }
  removePrePublish() {
    const pkg = json(this.packageJsonPath);
    if (!pkg.exists())
      return false;
    const data = pkg.read();
    const scripts = data.scripts || {};
    if (scripts.prepublishOnly) {
      delete scripts.prepublishOnly;
      pkg.write({ ...data, scripts });
      return true;
    }
    return false;
  }
  removeAll() {
    this.removePreCommit();
    this.removePrePublish();
  }
  isPreCommitInstalled() {
    const hookPath = this.getHookPath("pre-commit");
    if (!fs5.existsSync(hookPath))
      return false;
    const content = fs5.readFileSync(hookPath, "utf-8");
    return content.includes("npm test");
  }
  isPrePublishInstalled() {
    const pkg = json(this.packageJsonPath);
    if (!pkg.exists())
      return false;
    const data = pkg.read();
    const scripts = data.scripts || {};
    return !!scripts.prepublishOnly;
  }
  runTests() {
    const start = Date.now();
    try {
      const output = execSyncWithMemoryLimit("npm test 2>&1", {
        cwd: this.projectRoot,
        encoding: "utf-8",
        timeout: 120000
      }, "default");
      return { passed: true, output, duration: Date.now() - start };
    } catch (err) {
      const error = err;
      return {
        passed: false,
        output: error.stdout || error.message || "Test execution failed",
        duration: Date.now() - start
      };
    }
  }
  runCoverageCheck(threshold = 0.8) {
    const start = Date.now();
    try {
      const output = execSyncWithMemoryLimit(`npm run test:coverage 2>&1`, {
        cwd: this.projectRoot,
        encoding: "utf-8",
        timeout: 120000
      }, "coverage");
      const coverageMatch = output.match(/(\d+(?:\.\d+)?)\s*%/);
      const coveragePercent = coverageMatch ? parseFloat(coverageMatch[1]) : 0;
      const passed = coveragePercent / 100 >= threshold;
      return {
        passed,
        output: `${output}
Coverage: ${coveragePercent}% (threshold: ${threshold * 100}%)`,
        duration: Date.now() - start
      };
    } catch (err) {
      const error = err;
      return {
        passed: false,
        output: error.stdout || error.message || "Coverage check failed",
        duration: Date.now() - start
      };
    }
  }
  getHookPath(type) {
    return path3.join(this.gitDir, "hooks", type);
  }
  ensureHooksDir() {
    const hooksDir = path3.join(this.gitDir, "hooks");
    if (!fs5.existsSync(hooksDir)) {
      fs5.mkdirSync(hooksDir, { recursive: true });
    }
  }
}

