function extractFileReferencesFromText(text) {
  if (!text)
    return [];
  const files = [];
  const seen = new Set;
  const patterns = [
    /(?:src|lib|test|tests|docs|bin|scripts|config)\/[\w/.-]+\.[a-z]+/g,
    /\.{1,2}\/[\w/.-]+\.[a-z]+/g,
    /[\w-]+\/[\w/.-]+\.(ts|tsx|js|jsx|py|go|java|rs|json|yaml|yml|md)/g
  ];
  for (const pattern of patterns) {
    const matches = text.match(pattern);
    if (matches) {
      for (const match of matches) {
        if (!seen.has(match)) {
          seen.add(match);
          files.push(match);
        }
      }
    }
  }
  return files;
}
function findMissingFiles(filePaths, cwd) {
  const missing = [];
  for (const fp of filePaths) {
    const absolutePath = path14.resolve(cwd, fp);
    if (!fs18.existsSync(absolutePath)) {
      missing.push(fp);
    }
  }
  return missing;
}
