// src/utils/harness-code-reviewer.ts
init_prompt_templates();
init_i18n();
init_session_id_mapper();
init_session_lock_cleanup();
class HarnessCodeReviewer {
  config;
  debugLogger;
  constructor(config) {
    this.config = config;
    this.debugLogger = new DebugLogger({
      cwd: config.cwd,
      enabled: config.debug
    });
  }
  async review(task, devReport, retryContext) {
    let texts;
    try {
      texts = t(this.config.cwd);
    } catch {
      texts = getI18n("zh");
    }
    console.log(`
\uD83D\uDD0D ${texts.harness.logs.codeReviewPhase}`);
    console.log(`   ${texts.harness.logs.taskLabel}: ${task.title}`);
    const verdict = {
      taskId: task.id,
      result: "PASS",
      reason: "",
      codeQualityIssues: [],
      failedCheckpoints: [],
      reviewedAt: new Date().toISOString(),
      reviewedBy: "code_reviewer"
    };
    if (devReport.status !== "success") {
      verdict.result = "NOPASS";
      verdict.reason = `${texts.harness.logs.devPhaseNotComplete}: ${devReport.status}`;
      if (devReport.error) {
        verdict.reason += ` - ${devReport.error}`;
      }
      await this.saveReport(task.id, verdict);
      return verdict;
    }
    try {
      const codeReviewCheckpoints = this.getCodeReviewCheckpoints(task);
      console.log(`   \uD83D\uDCCB ${texts.harness.logs.codeReviewCheckpoints}: ${codeReviewCheckpoints.length}`);
      if (codeReviewCheckpoints.length === 0) {
        verdict.result = "PASS";
        verdict.reason = texts.harness.logs.noCodeReviewCheckpoints;
        console.log(`   ✅ ${texts.harness.logs.noCodeReviewCheckpoints}`);
      } else {
        const reviewResult = await this.runCodeReview(task, devReport, codeReviewCheckpoints, retryContext);
        verdict.result = reviewResult.passed ? "PASS" : "NOPASS";
        verdict.reason = reviewResult.reason;
        verdict.codeQualityIssues = reviewResult.issues;
        verdict.failedCheckpoints = reviewResult.failedCheckpoints;
        verdict.details = reviewResult.details;
        const contradiction = detectContradiction(verdict.result, verdict.reason || "");
        if (contradiction.hasContradiction && contradiction.correctedResult) {
          console.log(`   ⚠️  ${texts.harness.logs.contradictionDetected}: ${contradiction.reason}`);
          verdict.result = contradiction.correctedResult;
          verdict.reason += ` [${texts.harness.logs.contradictionDetected}: ${contradiction.reason}]`;
        }
        if (verdict.result === "PASS") {
          console.log(`
   ✅ ${texts.harness.logs.codeReviewPassed}`);
        } else {
          console.log(`
   ❌ ${texts.harness.logs.codeReviewFailed}: ${verdict.reason}`);
        }
      }
    } catch (error) {
      verdict.result = "NOPASS";
      verdict.reason = `${texts.harness.logs.codeReviewError}: ${error instanceof Error ? error.message : String(error)}`;
      console.log(`
   ❌ ${texts.harness.logs.codeReviewError}: ${verdict.reason}`);
      this.debugLogger.logError(task.id, "code_review", error instanceof Error ? error : new Error(String(error)), { verdict });
    }
    await this.saveReport(task.id, verdict);
    return verdict;
  }
  getCodeReviewCheckpoints(task) {
    return filterCheckpoints(task, (cp) => cp.category === "code_review" || cp.verification?.method === "code_review" || cp.verification?.method === "lint" || cp.verification?.method === "architect_review" || cp.description?.toLowerCase().includes("[ai review]"));
  }
  async runCodeReview(task, devReport, checkpoints, retryContext) {
    let texts;
    try {
      texts = t(this.config.cwd);
    } catch {
      texts = getI18n("zh");
    }
    const prompt = this.buildCodeReviewPrompt(task, devReport, checkpoints, retryContext);
    console.log(`
   \uD83D\uDCDD ${texts.harness.logs.codeReviewPromptGenerated}`);
    this.debugLogger.logPrompt(task.id, "code_review", prompt);
    console.log(`
   \uD83E\uDD16 ${texts.harness.logs.startingCodeReviewSession}`);
    const agent = getAgent(this.config.cwd);
    const effectiveTools = buildEffectiveTools("codeReview", this.config.cwd, task);
    const phaseOptions = this.config.perPhaseOptions?.["codeReview"];
    const internalId = sessionIdMapper.buildStableInternalId(task.id, "codeReview", "cr");
    const probe = sessionIdMapper.probeSessionState(internalId);
    const sessionId = probe.state === "active" ? probe.cliUuid : sessionIdMapper.generate(internalId, task.id, "codeReview", `${process.pid}-${Date.now()}`);
    ensureCleanSessionSlot(sessionId);
    const invokeOptions = {
      allowedTools: effectiveTools.tools,
      timeout: Math.floor(this.config.timeout / REVIEW_TIMEOUT_RATIO),
      cwd: this.config.cwd,
      outputFormat: "text",
      dangerouslySkipPermissions: effectiveTools.skipPermissions,
      sessionId,
      sessionState: probe.state,
      bare: phaseOptions?.bare,
      noSessionPersistence: phaseOptions?.noSessionPersistence,
      mcpConfig: phaseOptions?.mcpConfig,
      strictMcpConfig: phaseOptions?.strictMcpConfig,
      pluginDir: phaseOptions?.pluginDir,
      pluginUrl: phaseOptions?.pluginUrl,
      disableSlashCommands: phaseOptions?.disableSlashCommands,
      effort: phaseOptions?.effort,
      maxBudgetUsd: phaseOptions?.maxBudgetUsd,
      debug: phaseOptions?.debug
    };
    const engine = createSessionAwareEngine("markdown", [codeReviewVerdictResultMarker, codeReviewVerdictHasReason], 1);
    const engineResult = await engine.runWithFeedback(agent.invoke.bind(agent), prompt, invokeOptions);
    if (engineResult.retries > 0) {
      console.log(`   \uD83D\uDD04 ${texts.harness.logs.codeReviewRetry.replace("{retries}", String(engineResult.retries))}`);
    }
    if (!engineResult.result.success) {
      this.debugLogger.logError(task.id, "code_review", new Error(engineResult.result.error || "Code review session failed"), { engineResult });
      return {
        passed: false,
        reason: `${texts.harness.logs.codeReviewSessionFailed}: ${engineResult.result.error || "unknown error"}`,
        issues: [],
        failedCheckpoints: []
      };
    }
    this.debugLogger.logAIResponse(task.id, "code_review", engineResult.result.output || "", {
      retries: engineResult.retries,
      success: engineResult.result.success
    });
    return this.parseCodeReviewResult(engineResult.result.output || "");
  }
  buildCodeReviewPrompt(task, devReport, checkpoints, retryContext) {
    let texts;
    try {
      texts = t(this.config.cwd);
    } catch {
      texts = getI18n("zh");
    }
    const roleTemplate = getCodeReviewRoleTemplate(task.recommendedRole);
    const retryContextSection = retryContext?.previousFailureReason ? `## ${texts.harness.logs.previousReviewFailureReason}

${texts.harness.logs.previousCodeReviewFailed}:

> ${retryContext.previousFailureReason}

${texts.harness.logs.ensureFixesCover}.` : "";
    const descriptionSection = task.description ? `## ${texts.harness.taskDescription}
${task.description}` : "";
    const checkpointsList = checkpoints.map((cp, i) => {
      let line = `${i + 1}. [${cp.id}] ${cp.description}`;
      if (cp.verification?.commands) {
        line += `
   ${texts.harness.logs.verificationCommands}: ${cp.verification.commands.join(", ")}`;
      }
      return line;
    }).join(`
`);
    const changesSection = devReport.changes.length > 0 ? `## ${texts.harness.logs.developerDeclaredChanges}
${devReport.changes.map((change) => `- ${change}`).join(`
`)}` : "";
    const evidenceSection = devReport.evidence.length > 0 ? `## ${texts.harness.logs.submittedEvidence}
${devReport.evidence.map((evidence) => `- ${evidence}`).join(`
`)}` : "";
    const reviewFocus = roleTemplate.reviewFocus.map((focus, i) => `${i + 1}. ${focus}`).join(`
`);
    const customRequirements = loadCustomRequirements("codeReview", this.config.cwd);
    const template = loadPromptTemplate("codeReview", this.config.cwd);
    return resolveTemplate(template, {
      roleDeclaration: roleTemplate.roleDeclaration,
      taskId: task.id,
      title: task.title,
      descriptionSection,
      checkpointsList,
      changesSection,
      evidenceSection,
      customRequirements,
      reviewFocus,
      retryContextSection
    }).replace(/\n{3,}/g, `

`);
  }
  parseCodeReviewResult(output) {
    const parsed = parseVerdictResult(output, {
      resultField: "审核结果",
      reasonField: "原因",
      listField: "代码质量问题",
      checkpointField: "未通过的检查点",
      detailsField: "详细反馈"
    });
    return {
      passed: parsed.passed,
      reason: parsed.reason,
      issues: parsed.items,
      failedCheckpoints: parsed.failedCheckpoints,
      details: parsed.details
    };
  }
  async saveReport(taskId, verdict) {
    const reportPath = getReportPath(taskId, "code-review", this.config.cwd);
    const content = this.formatReport(verdict);
    await saveReport(reportPath, content);
  }
  formatReport(verdict) {
    let texts;
    try {
      texts = t(this.config.cwd);
    } catch {
      texts = getI18n("zh");
    }
    const lines = [
      `# ${texts.harness.reports.codeReviewReportTitle} - ${verdict.taskId}`,
      "",
      `**${texts.harness.reports.resultLabel}**: ${verdict.result === "PASS" ? "✅ PASS" : "❌ NOPASS"}`,
      `**${texts.harness.reports.reviewedAtLabel}**: ${verdict.reviewedAt}`,
      `**${texts.harness.reports.reviewedByLabel}**: ${verdict.reviewedBy}`,
      "",
      `## ${texts.harness.reports.reasonSection}`,
      verdict.reason,
      ""
    ];
    if (verdict.codeQualityIssues.length > 0) {
      lines.push(`## ${texts.harness.reports.codeQualityIssuesSection}`);
      verdict.codeQualityIssues.forEach((issue) => {
        lines.push(`- ${issue}`);
      });
      lines.push("");
    }
    if (verdict.failedCheckpoints.length > 0) {
      lines.push(`## ${texts.harness.reports.failedCheckpointsSection}`);
      verdict.failedCheckpoints.forEach((checkpoint) => {
        lines.push(`- ${checkpoint}`);
      });
      lines.push("");
    }
    if (verdict.details) {
      lines.push(`## ${texts.harness.reports.detailsSection}`);
      lines.push(verdict.details);
      lines.push("");
    }
    return lines.join(`
`);
  }
}

