async function executeRules(rules, context) {
  for (const rule of rules) {
    const passed = await rule.check(context);
    if (!passed) {
      return {
        passed: false,
        targetPhase: rule.onFailure.targetPhase,
        reason: `${rule.id}: ${rule.onFailure.reason}`
      };
    }
  }
  return { passed: true };
}
